// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// Resource nodes: a rock, a tree, a bush or a fishing spot. A player presses E beside one, stays there while the
// bar fills, and its kind lands in their right hand as a carried item (the carry module's giveItem), ready for a
// Work Station or a script. After its uses it runs out: it stays where it is with a floating "Back in 0:24"
// line (or hides, when the node says so) and comes back later. The Multiplayer Server decides
// who gathers and what is left; every client draws what it published. The Resource Node prefab registers
// itself; a creator script imports this module to react:
//
//   import { onHarvest, usesLeft, refillNode } from './runtime/harvest'
//
// A node's id is its entity Name, matched trimmed and case-insensitively, like zone names.
//
// Either side:
//   usesLeft(node)        → number | null — uses before it runs out; null for a node that never does or no node
//   isGathering(node)     → wallet | null — who is gathering there right now
//   onHarvest(fn)         → remover. fn(event) for every change: on the server as it happens, on each client when
//                           the server tells it. event = { type, node, kind, player? }, type 'gather' (a player got
//                           one; `player` is set) | 'empty' (it ran out) | 'back' (it came back full).
// Server only (inside if (isServer())):
//   refillNode(node)      → boolean — back to full at once (an event, a purchase, a quest step)
//
// Every round start refills every node. What the kind looks like in the hand comes from a Pickup Item with that
// kind (supply "look only" is enough); without one the hand shows a plain box.
// Wire names: game.state.harvest, the game request 'harvest.act' and the broadcast 'harvest.event'.
import {
  Billboard,
  BillboardMode,
  GltfContainer,
  Material,
  MeshCollider,
  MeshRenderer,
  PlayerIdentityData,
  Schemas,
  TextShape,
  Transform,
  VisibilityComponent,
  engine,
  type Entity,
  type LastWriteWinElementSetComponentDefinition,
  type PBMeshCollider
} from '@dcl/sdk/ecs'
import { Color4 } from '@dcl/sdk/math'
import { isServer } from '@dcl/sdk/network'
import { game, reportProblem, type Player } from './game'
import { giveItem, heldBy } from './carry'
import { addInteractions, sayNotice, type PromptCandidate } from './interactPrompt'
import { entityWorld } from './sceneNames'
import { verbWith } from './pure/interactPick'
import { zoneKey } from './pure/zoneRegistry'
import {
  HARVEST_EVENT_TYPES,
  emptyLine,
  freshHarvest,
  gatherProgress,
  isEmpty,
  leaveHarvest,
  nodeRow,
  readHarvest,
  startGather,
  tickHarvest,
  type HarvestEvent,
  type HarvestEventType,
  type HarvestState,
  type NodeRule
} from './pure/harvestRules'

export type { HarvestEvent, HarvestEventType }

export type WhenEmpty = 'show timer' | 'hide'

export interface NodeSpec {
  entity: Entity
  kind: string
  gatherVerb: string
  seconds: number
  uses: number
  respawnSeconds: number
  whenEmpty: WhenEmpty
  emptyText: string
  emptyRoundText: string
  range: number
  barHeight: number
}

interface Node extends NodeSpec { id: string; name: string }
interface Bar { root: Entity; back: Entity; fill: Entity; shown: number }
interface Label { entity: Entity; text: string }
interface Stash { collider: PBMeshCollider | null; gltf: { visible: number; invisible: number } | null }

interface HarvestHub {
  nodes: Map<string, Node>
  rules: Record<string, NodeRule>
  side: 'server' | 'client' | null
  state: HarvestState
  view: HarvestState
  listeners: Set<(event: HarvestEvent) => void>
  bars: Map<string, Bar>
  labels: Map<string, Label>
  emptied: Map<Entity, Stash>
}

const KEY = '__dclHarvest_v1'
const STATE_KEY = 'harvest'
const REQUEST = 'harvest.act'
const EVENT = 'harvest.event'
// the server sees positions ~10 times a second, so its range check is generous
const SLACK_M = 1.5
const BAR_WIDTH = 0.8

function isHub(value: unknown): value is HarvestHub {
  return typeof value === 'object' && value !== null && 'nodes' in value && value.nodes instanceof Map &&
    'rules' in value && 'listeners' in value && 'emptied' in value && 'labels' in value
}

function hub(): HarvestHub {
  const globals = globalThis as unknown as Record<string, unknown>
  const current = globals[KEY]
  if (isHub(current)) return current
  const created: HarvestHub = {
    nodes: new Map(), rules: {}, side: null, state: freshHarvest(), view: freshHarvest(),
    listeners: new Set(), bars: new Map(), labels: new Map(), emptied: new Map()
  }
  globals[KEY] = created
  return created
}

type NameComponent = LastWriteWinElementSetComponentDefinition<{ value: string }>

function nameOf(entity: Entity): string {
  const names = (engine.getComponentOrNull('core-schema::Name') ??
    engine.defineComponent('core-schema::Name', { value: Schemas.String })) as NameComponent
  return names.getOrNull(entity)?.value.trim() ?? ''
}

function myAddress(): string {
  return PlayerIdentityData.getOrNull(engine.PlayerEntity)?.address.toLowerCase() ?? ''
}

// ---------------------------------------------------------------- registration

/** Called by the Resource Node prefab from start(), on both sides. */
export function registerNode(spec: NodeSpec): void {
  const h = hub()
  const name = nameOf(spec.entity)
  const id = zoneKey(name)
  if (id === '' || spec.kind.trim() === '') {
    reportProblem('Resource Node', 'A Resource Node needs a Name and a kind: give the entity a Name and set what it gives.')
    return
  }
  if (h.nodes.has(id)) {
    reportProblem('Resource Node', `Two Resource Nodes are named "${name}". Give each its own Name.`)
    return
  }
  h.nodes.set(id, { ...spec, kind: spec.kind.trim(), id, name })
  h.rules[id] = {
    kind: spec.kind.trim(),
    ms: Math.max(0, spec.seconds) * 1000,
    uses: Math.max(0, Math.floor(spec.uses)),
    respawnMs: Math.max(0, spec.respawnSeconds) * 1000
  }
  start(h)
}

function start(h: HarvestHub): void {
  if (h.side !== null) return
  if (isServer()) {
    h.side = 'server'
    startServer(h)
  } else {
    h.side = 'client'
    startClient(h)
  }
}

// ---------------------------------------------------------------- reads (either side)

function current(h: HarvestHub): HarvestState {
  return h.side === 'server' ? h.state : h.view
}

export function usesLeft(node: string): number | null {
  const h = hub()
  const id = zoneKey(node)
  const rule = h.rules[id]
  if (rule === undefined || rule.uses <= 0) return null
  return nodeRow(current(h), id, rule).left
}

export function isGathering(node: string): Player | null {
  return current(hub()).nodes[zoneKey(node)]?.by ?? null
}

export function onHarvest(fn: (event: HarvestEvent) => void): () => void {
  const h = hub()
  h.listeners.add(fn)
  return () => { h.listeners.delete(fn) }
}

function tell(h: HarvestHub, event: HarvestEvent): void {
  for (const listener of [...h.listeners]) {
    try {
      listener(event)
    } catch (e) {
      console.error(`[harvest] an onHarvest listener failed on "${event.type}":`, e)
    }
  }
}

// ---------------------------------------------------------------- server

function named(h: HarvestHub, event: HarvestEvent): HarvestEvent {
  return { ...event, node: h.nodes.get(event.node)?.name ?? event.node }
}

function publish(h: HarvestHub): void {
  game.setState({ [STATE_KEY]: h.state })
}

function emit(h: HarvestHub, events: HarvestEvent[]): void {
  for (const raw of events) {
    const event = named(h, raw)
    tell(h, event)
    game.broadcast(EVENT, event)
  }
}

export function refillNode(node: string): boolean {
  const h = hub()
  if (!isServer()) {
    console.error('[you] refillNode only runs on the server. Put this line inside if (isServer()).')
    return false
  }
  const id = zoneKey(node)
  const rule = h.rules[id]
  if (rule === undefined) return false
  h.state = { nodes: { ...h.state.nodes, [id]: { left: rule.uses } } }
  publish(h)
  emit(h, [{ type: 'back', node: id, kind: rule.kind }])
  return true
}

function near(h: HarvestHub, player: Player, id: string): boolean {
  const node = h.nodes.get(id)
  const at = node === undefined ? null : entityWorld(node.entity)?.position ?? null
  const feet = game.positionOf(player)
  if (node === undefined || at === null || feet === null) return node !== undefined
  return Math.hypot(feet.x - at.x, feet.z - at.z) <= node.range + SLACK_M
}

function readNode(data: unknown): string | null {
  if (typeof data !== 'object' || data === null) return null
  const node = (data as Record<string, unknown>).node
  return typeof node === 'string' ? zoneKey(node) : null
}

function serverAct(h: HarvestHub, data: unknown, player: Player): { ok: boolean; message?: string } {
  const id = readNode(data)
  if (id === null || h.rules[id] === undefined) return { ok: false }
  if (!near(h, player, id)) return { ok: false, message: 'Move closer' }
  const result = startGather(h.state, id, player.toLowerCase(), h.rules[id], game.now(), heldBy(player) === null)
  if (!result.accepted) return { ok: false, message: result.message }
  if (result.state !== h.state) {
    h.state = result.state
    publish(h)
  }
  return { ok: true }
}

function serverTick(h: HarvestHub): void {
  const result = tickHarvest(h.state, h.rules, game.now(), (player, id) => near(h, player, id),
    (player, kind) => giveItem(player, kind))
  if (!result.changed) return
  h.state = result.state
  publish(h)
  emit(h, result.events)
}

function startServer(h: HarvestHub): void {
  game.onReady(() => publish(h))
  game.onRequest(REQUEST, (data: unknown, player) => serverAct(h, data, player))
  game.onPlayerLeave((player) => {
    h.state = leaveHarvest(h.state, player.toLowerCase())
    publish(h)
  })
  game.onRoundStart(() => {
    h.state = freshHarvest()
    publish(h)
  })
  game.every(0.1, () => serverTick(h))
}

// ---------------------------------------------------------------- client

function readEvent(data: unknown): HarvestEvent | null {
  if (typeof data !== 'object' || data === null) return null
  const raw = data as Record<string, unknown>
  if (!HARVEST_EVENT_TYPES.includes(raw.type as HarvestEventType) || typeof raw.node !== 'string' || typeof raw.kind !== 'string') return null
  const event: HarvestEvent = { type: raw.type as HarvestEventType, node: raw.node, kind: raw.kind }
  if (typeof raw.player === 'string') event.player = raw.player
  return event
}

function replyOk(reply: unknown): { ok: boolean; message: string } {
  if (typeof reply !== 'object' || reply === null) return { ok: false, message: '' }
  const raw = reply as Record<string, unknown>
  return { ok: raw.ok === true, message: typeof raw.message === 'string' ? raw.message : '' }
}

function gather(node: Node): void {
  game.request<unknown>(REQUEST, { node: node.id }).then((reply) => {
    const answer = replyOk(reply)
    if (!answer.ok && answer.message !== '') sayNotice(answer.message)
  }, (error: unknown) => {
    sayNotice('No answer from the server. Try again.')
    console.log(`[harvest] gather failed: ${String(error)}`)
  })
}

function candidates(h: HarvestHub): PromptCandidate[] {
  const me = myAddress()
  if (me === '' || heldBy(me) !== null) return []
  const out: PromptCandidate[] = []
  for (const node of h.nodes.values()) {
    const rule = h.rules[node.id]
    const row = nodeRow(h.view, node.id, rule)
    if (isEmpty(row, rule) || row.by !== undefined) continue
    const at = entityWorld(node.entity)?.position ?? null
    if (at === null) continue
    out.push({ key: `node:${node.id}`, position: at, range: node.range, height: node.barHeight + 0.4, actions: [{
      verb: verbWith(node.gatherVerb, node.kind), button: 'primary',
      run: (pressed) => { if (pressed) gather(node) }
    }] })
  }
  return out
}

// A node set to hide while empty disappears and stops blocking: its collider is put aside and given back when it returns.
function setEmptied(h: HarvestHub, entity: Entity, emptied: boolean): void {
  if (h.emptied.has(entity) === emptied) return
  if (emptied) {
    const collider = MeshCollider.getOrNull(entity)
    const gltf = GltfContainer.getOrNull(entity)
    h.emptied.set(entity, {
      collider: collider === null ? null : JSON.parse(JSON.stringify(collider)) as PBMeshCollider,
      gltf: gltf === null ? null : { visible: gltf.visibleMeshesCollisionMask ?? 0, invisible: gltf.invisibleMeshesCollisionMask ?? 3 }
    })
    if (collider !== null) MeshCollider.deleteFrom(entity)
    if (gltf !== null) {
      const mutable = GltfContainer.getMutable(entity)
      mutable.visibleMeshesCollisionMask = 0
      mutable.invisibleMeshesCollisionMask = 0
    }
    VisibilityComponent.createOrReplace(entity, { visible: false, propagateToChildren: true })
    return
  }
  const stash = h.emptied.get(entity)
  h.emptied.delete(entity)
  if (stash?.collider !== null && stash?.collider !== undefined) MeshCollider.createOrReplace(entity, stash.collider)
  if (stash?.gltf !== null && stash?.gltf !== undefined && GltfContainer.has(entity)) {
    const mutable = GltfContainer.getMutable(entity)
    mutable.visibleMeshesCollisionMask = stash.gltf.visible
    mutable.invisibleMeshesCollisionMask = stash.gltf.invisible
  }
  VisibilityComponent.createOrReplace(entity, { visible: true, propagateToChildren: true })
}

function removeBar(h: HarvestHub, id: string): void {
  const bar = h.bars.get(id)
  if (bar === undefined) return
  for (const entity of [bar.fill, bar.back, bar.root]) engine.removeEntity(entity)
  h.bars.delete(id)
}

function createBar(h: HarvestHub, node: Node): Bar | null {
  const at = entityWorld(node.entity)?.position ?? null
  if (at === null) return null
  const root = engine.addEntity()
  Transform.create(root, { position: { x: at.x, y: at.y + node.barHeight, z: at.z } })
  Billboard.create(root, { billboardMode: BillboardMode.BM_Y })
  const back = engine.addEntity()
  Transform.create(back, { parent: root, scale: { x: BAR_WIDTH, y: 0.12, z: 0.02 } })
  MeshRenderer.setBox(back)
  Material.setPbrMaterial(back, { albedoColor: Color4.create(0.1, 0.1, 0.12, 1) })
  const fill = engine.addEntity()
  MeshRenderer.setBox(fill)
  Material.setPbrMaterial(fill, { albedoColor: Color4.create(0.45, 0.85, 0.4, 1), emissiveColor: { r: 0.3, g: 0.8, b: 0.3 }, emissiveIntensity: 0.6 })
  const bar: Bar = { root, back, fill, shown: -1 }
  h.bars.set(node.id, bar)
  return bar
}

function drawBar(h: HarvestHub, node: Node, progress: number): void {
  const bar = h.bars.get(node.id) ?? createBar(h, node)
  if (bar === null || Math.abs(bar.shown - progress) < 0.005) return
  bar.shown = progress
  const width = Math.max(0.001, (BAR_WIDTH - 0.04) * progress)
  Transform.createOrReplace(bar.fill, {
    parent: bar.root,
    position: { x: -(BAR_WIDTH - 0.04 - width) / 2, y: 0, z: 0 },
    scale: { x: width, y: 0.08, z: 0.03 }
  })
}

function removeLabel(h: HarvestHub, id: string): void {
  const label = h.labels.get(id)
  if (label === undefined) return
  engine.removeEntity(label.entity)
  h.labels.delete(id)
}

function drawLabel(h: HarvestHub, node: Node, text: string): void {
  let label = h.labels.get(node.id)
  if (label === undefined) {
    const at = entityWorld(node.entity)?.position ?? null
    if (at === null) return
    const entity = engine.addEntity()
    Transform.create(entity, { position: { x: at.x, y: at.y + node.barHeight, z: at.z } })
    Billboard.create(entity, { billboardMode: BillboardMode.BM_ALL })
    label = { entity, text: '' }
    h.labels.set(node.id, label)
  }
  if (label.text === text) return
  label.text = text
  TextShape.createOrReplace(label.entity, {
    text,
    fontSize: 2,
    textColor: { r: 1, g: 1, b: 1, a: 0.9 },
    outlineColor: { r: 0, g: 0, b: 0 },
    outlineWidth: 0.15
  })
}

function clientTick(h: HarvestHub): void {
  h.view = readHarvest(game.state[STATE_KEY])
  const now = game.now()
  for (const node of h.nodes.values()) {
    const rule = h.rules[node.id]
    const row = nodeRow(h.view, node.id, rule)
    const empty = isEmpty(row, rule)
    setEmptied(h, node.entity, empty && node.whenEmpty === 'hide')
    const line = node.whenEmpty === 'show timer' ? emptyLine(row, rule, now, node.emptyText, node.emptyRoundText) : null
    if (line === null) removeLabel(h, node.id)
    else drawLabel(h, node, line)
    if (row.since === undefined || rule.ms <= 0) removeBar(h, node.id)
    else drawBar(h, node, gatherProgress(row, rule, now))
  }
}

function startClient(h: HarvestHub): void {
  game.onBroadcast(EVENT, (data: unknown) => {
    const event = readEvent(data)
    if (event !== null) tell(h, event)
  })
  addInteractions(() => candidates(h))
  engine.addSystem(() => clientTick(h), undefined, 'runtime-harvest')
}
